    "notes": "了 (le) hat zwei Hauptfunktionen. Direkt nach dem Verb markiert es eine abgeschlossene Handlung, meist mit Mengenangabe: 我买了两本书. Am Satzende zeigt es eine Veränderung oder neue Situation an: 下雨了 „es regnet jetzt“, 我饿了 „ich habe Hunger bekommen“. 了 ist kein Vergangenheitsmarker: Gewohnheiten in der Vergangenheit stehen ohne 了, und die Verneinung lautet 没 + Verb ohne 了 (我没吃, nicht 我没吃了).",
